package net.officefloor.hq.app.sheet;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A change was asked of an archived sheet. */
@ResponseStatus(HttpStatus.CONFLICT)
public class SheetArchivedException extends RuntimeException {

    public SheetArchivedException(String sheetId) {
        super("Sheet " + sheetId + " is archived and may not be changed");
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.DelegationService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The records that only report figures: they never say on whose behalf the change was made. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    private static final Pattern SHEET_BY = Pattern.compile("^(\\S+) sheet=(\\S+) by=(\\S+)");

    private final Path file;
    private final ObjectProvider<DelegationService> delegations;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path,
            ObjectProvider<DelegationService> delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
    }

    /**
     * The record as written: a change made by a user acting as a steward by delegation on the sheet's today ends with
     * {@code for=<the steward who delegated>}; a record that only reports figures is left as it is.
     */
    private String onBehalf(String entry) {
        Matcher m = SHEET_BY.matcher(entry);
        if (!m.find() || FIGURES_ONLY.contains(m.group(1))) {
            return entry;
        }
        return delegations.getObject().delegatorOf(m.group(2), m.group(3)).map(s -> entry + " for=" + s).orElse(entry);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String record) {
        String entry = onBehalf(record);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
== V1__sheet.sql
-- A sheet is the unit everything else in the app is kept under. It is created the first time its
-- id is loaded.
CREATE TABLE sheet (
    id         VARCHAR(100) PRIMARY KEY,
    created_by VARCHAR(100) NOT NULL
);
== V2__sheet_today.sql
-- Each sheet keeps its own "today": every date-dependent decision and default date uses it, never
-- the real clock. A sheet starts with the real date of the day it was created.
ALTER TABLE sheet ADD COLUMN today DATE;
UPDATE sheet SET today = CURRENT_DATE WHERE today IS NULL;
ALTER TABLE sheet ALTER COLUMN today SET NOT NULL;
== V3__person.sql
-- The people on a sheet, each with a name and a grade (A, B or C). Listed in the order they were
-- added, which is the order of their ids.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
== V4__person_name_unique.sql
-- A person's name is unique on its sheet, compared without regard to case and ignoring spaces
-- before and after it. Names are kept with those surrounding spaces removed; name_key is the
-- trimmed, lower-cased name the uniqueness is checked on.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200);
UPDATE person SET name_key = LOWER(name);
ALTER TABLE person ALTER COLUMN name_key SET NOT NULL;
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
== V5__claim.sql
-- A person's claims, each with an amount (0.00 or more, two decimals), a date and a note that may
-- be empty. Listed newest first, which is the reverse order of their ids.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
== V6__rate.sql
-- The rate for each grade on a sheet: a percent with two decimals (0.00 or more). A grade with no
-- row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
== V7__claim_status.sql
-- A claim's status: DRAFT when added, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
== V8__claim_number.sql
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A DRAFT has none and voiding a claim clears it. The sheet keeps the last number it gave out.
ALTER TABLE sheet ADD COLUMN last_claim_number BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number BIGINT;
== V9__claim_settled_due.sql
-- A claim's due as it was when it was settled: its amount times its person's grade's rate then,
-- rounded half up to cents. Null while the claim is not settled, or when the grade had no rate
-- (that due stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(14, 2);
== V10__rate_from_date.sql
-- A rate may carry a from-date: it applies from that date on, until a later-dated rate for the same
-- grade takes over. A rate with no from-date applies from the beginning of time. A grade has at
-- most one rate per from-date (and at most one with none); from_key stands in for the missing
-- from-date so the unique index covers that one too.
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
== V11__claim_opened_by.sql
-- Who opened a claim: the signed-in user's name, set when it is opened; null for a DRAFT. That user may not
-- settle the claim (four eyes).
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(100);
== V12__person_version.sql
-- The version of a person, raised by one each time the person is saved. An editor sends back the
-- version it loaded; a save of a version someone else has since replaced is refused.
ALTER TABLE person ADD COLUMN version BIGINT DEFAULT 0 NOT NULL;
== V13__statement.sql
-- A statement taken of a person: their due-total then (two decimals, or n/a), how many of their
-- claims counted, and the sheet's today when it was taken. A person's statements are in the order
-- of their ids; the last one is the person's last statement.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    taken_on  DATE         NOT NULL,
    due_total VARCHAR(20)  NOT NULL,
    claims    INT          NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);

-- Whether the claim is bound by its person's last statement, and the due it was bound to (null when
-- it had none then: n/a). A bound claim shows and totals that due until the next statement.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);
== V14__period.sql
-- The periods of a sheet: a name, unique on the sheet, and a from and to date, both inclusive, with
-- from on or before to. No two periods of a sheet overlap. A claim belongs to the period whose
-- dates contain its date, or to none.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(100) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
== V15__period_closed.sql
-- Whether a period is closed, and its due-total fixed when it was closed: the dues of the OPEN and
-- SETTLED claims dated in it, skipping those with no rate. Null while the period is open. No claim
-- dated in a closed period can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14, 2);
== V16__person_retired.sql
-- The date a person is retired from; null while they are not retired. A person with a date counts as
-- retired at once, whatever the date. No claim dated after it can be added or saved for them.
ALTER TABLE person ADD COLUMN retired_from DATE;
== V17__person_held.sql
-- Whether the person is on hold. While held, their OPEN claims count in no live total (their own claimed and
-- due-total, the sheet's totals, a period's); their SETTLED claims still do.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
== V18__role_clerk_limit.sql
-- A user's role on a sheet: clerk or steward. A user name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);

-- The highest due a clerk may settle, two decimals; NULL means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(12, 2) CHECK (clerk_limit >= 0);
== V19__sheet_floor.sql
-- The sheet's floor: a claim's live due is at least it. A settled claim's frozen due, a due bound by a statement
-- and a closed period's fixed total are left as they are. A sheet starts with a floor of 1.00.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(12, 2) DEFAULT 1.00 NOT NULL;
== V20__sheet_terms.sql
-- The sheet's terms: the number of days after its date that a claim is due by. A sheet starts with terms of 14.
ALTER TABLE sheet ADD COLUMN terms INT DEFAULT 14 NOT NULL CHECK (terms >= 0);
== V21__sheet_late_pct.sql
-- The sheet's late percent: an overdue claim's due gains this percent of its figure for every full 30 days it is
-- overdue. A sheet starts with a late percent of 0.00.
ALTER TABLE sheet ADD COLUMN late_pct DECIMAL(5, 2) DEFAULT 0.00 NOT NULL CHECK (late_pct >= 0);
== V22__person_patron.sql
-- The people a person names as their patrons, each another person on the same sheet, named at most
-- once. A person's backing is their patrons' due-totals added up.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id)
);
CREATE UNIQUE INDEX person_patron_pair ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
== V23__person_grade_dated.sql
-- A person's grade is dated: each grade applies from its from-date on, until the person's next
-- later-dated grade takes over. The first grade a person was given has no from-date and applies
-- from the beginning of time. A person has at most one grade per from-date (and at most one with
-- none); from_key stands in for the missing from-date so the unique index covers that one too.
CREATE TABLE person_grade (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT     NOT NULL REFERENCES person (id),
    grade     VARCHAR(1) NOT NULL,
    from_date DATE,
    from_key  DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'))
);
CREATE UNIQUE INDEX person_grade_person_from ON person_grade (person_id, from_key);
INSERT INTO person_grade (person_id, grade, from_date) SELECT id, grade, NULL FROM person;
ALTER TABLE person DROP COLUMN grade;
== V24__claim_corrects.sql
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the
-- same person that it corrects. Null for any other claim.
ALTER TABLE claim ADD COLUMN corrects BIGINT;

-- The amount may now be negative, but only on a correction. Its old CHECK (amount >= 0) has a
-- generated name, so the column is replaced (dropping it drops that check) and copied over.
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(12, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
== V25__rounding_policy_date.sql
-- The sheet's policy date: a claim dated before it rounds its live figures half up, one dated on or after it half to
-- even. Null (blank) means the sheet's today.
ALTER TABLE sheet ADD COLUMN policy_date DATE;
-- The date that decides how a claim rounds: its own date, or for a correction the date of the claim it corrects.
ALTER TABLE claim ADD COLUMN rounding_date DATE;
UPDATE claim SET rounding_date = claim_date;
UPDATE claim c SET rounding_date = (SELECT o.claim_date FROM claim o WHERE o.sheet_id = c.sheet_id
    AND o.person_id = c.person_id AND o.claim_number = c.corrects) WHERE c.corrects IS NOT NULL
    AND EXISTS (SELECT 1 FROM claim o WHERE o.sheet_id = c.sheet_id AND o.person_id = c.person_id
    AND o.claim_number = c.corrects);
ALTER TABLE claim ALTER COLUMN rounding_date SET NOT NULL;
== V26__period_numbering.sql
-- The sheet's period numbering from: while it is set and the sheet's today is on or after it, a claim opened is
-- numbered within its period (<period>-<n>), or X-<n> in no period. Null (blank) means off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number, and the number a correction names, are now text: a sheet-wide 1, 2, ... or P1-1, X-1, ...
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(255);
-- The last number given out in each period's sequence on a sheet (keyed by period name, or X for no period).
CREATE TABLE claim_number_sequence (
    sheet_id VARCHAR(100) NOT NULL,
    sequence_key VARCHAR(255) NOT NULL,
    last_number BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, sequence_key)
);
== V27__claim_pending.sql
-- A claim a clerk settles above the clerk limit waits as PENDING for a steward to approve (SETTLED) or reject (back
-- to OPEN). PENDING claims count toward the totals like OPEN ones. The status column is rebuilt to allow it.
ALTER TABLE claim ADD COLUMN status_new VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status_new IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'));
UPDATE claim SET status_new = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN status_new RENAME TO status;
== V28__claim_listed.sql
-- Where a claim stands in its person's list, newest first: the sheet's next list place when it is added, and again
-- when it is reassigned to another person, so it is listed as that person's newest claim whatever its date.
ALTER TABLE sheet ADD COLUMN last_listed BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN listed BIGINT;
UPDATE claim SET listed = id;
ALTER TABLE claim ALTER COLUMN listed SET NOT NULL;
UPDATE sheet SET last_listed = COALESCE((SELECT MAX(c.listed) FROM claim c WHERE c.sheet_id = sheet.id), 0);
== V29__grade_terms_claim_due_by.sql
-- Terms per grade: the days after its date a claim of a person of the grade is due by. A grade with no row uses the
-- sheet's terms.
CREATE TABLE grade_terms (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL,
    terms    INT          NOT NULL CHECK (terms >= 0)
);
CREATE UNIQUE INDEX grade_terms_sheet_grade ON grade_terms (sheet_id, grade);
-- A claim's due-by, fixed when it is added: its date plus the terms of its person's grade on that date. Claims already
-- kept take their date plus the sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
== V30__claim_log.sql
-- A claim's status log: one line per status it has had, in the order of their ids. Each keeps who made the change,
-- the sheet's today then, and the claim's due as it was computed at that moment (two decimals, or n/a).
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)  NOT NULL,
    by_user   VARCHAR(100) NOT NULL,
    logged_on DATE         NOT NULL,
    due       VARCHAR(20)  NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, id);
== V31__person_hold_interval.sql
-- A hold runs from its from-date to its to-date, both inclusive (no to-date: open-ended), and a person may have
-- several over time. Only the person's OPEN and PENDING claims dated within a hold, and not bound by a statement,
-- are left out of the live totals. A person held before keeps a hold from the beginning of time with no end.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE
);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
== V32__rate_to_date.sql
-- A rate may carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it, with no later rate in force on its date, has no rate. Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_to_after_from CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);
== V33__sheet_cap.sql
-- The sheet's cap: a person's due-total is at most it, the rest showing as their excess. A due-total of n/a is not
-- capped. A sheet starts with no cap (null).
ALTER TABLE sheet ADD COLUMN due_cap DECIMAL(12, 2);
== V34__period_person_total.sql
-- Each person's due-total for a period, fixed when the period was closed: the dues of their OPEN and SETTLED claims
-- dated in it, skipping those with no rate. One row per person on the sheet at that moment; none while the period is
-- open. The period's closed_total is the sum of these.
CREATE TABLE period_person_total (
    period_id BIGINT        NOT NULL REFERENCES period (id),
    person_id BIGINT        NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
== V35__dated_setting.sql
-- Settings that carry a figure are dated: each value is kept from its from-date. The value in force on a date is the
-- one with the latest from-date on or before it; before every from-date a key has the sheet's starting value (floor
-- 1.00, late-pct 0.00, terms 14; none for the clerk limit, the cap and a grade's terms). Keys: clerk-limit, floor,
-- terms, terms-A, terms-B, terms-C, late-pct, cap. A null value is "none" (no clerk limit, no cap).
CREATE TABLE dated_setting (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(20)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(20)
);
CREATE UNIQUE INDEX dated_setting_key_from ON dated_setting (sheet_id, setting_key, from_date);

-- The values already kept hold from the start.
INSERT INTO dated_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'clerk-limit', DATE '0001-01-01', CAST(clerk_limit AS VARCHAR(20)) FROM sheet WHERE clerk_limit IS NOT NULL;
INSERT INTO dated_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'floor', DATE '0001-01-01', CAST(due_floor AS VARCHAR(20)) FROM sheet WHERE due_floor <> 1.00;
INSERT INTO dated_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'terms', DATE '0001-01-01', CAST(terms AS VARCHAR(20)) FROM sheet WHERE terms <> 14;
INSERT INTO dated_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'late-pct', DATE '0001-01-01', CAST(late_pct AS VARCHAR(20)) FROM sheet WHERE late_pct <> 0.00;
INSERT INTO dated_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT id, 'cap', DATE '0001-01-01', CAST(due_cap AS VARCHAR(20)) FROM sheet WHERE due_cap IS NOT NULL;
INSERT INTO dated_setting (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, 'terms-' || grade, DATE '0001-01-01', CAST(terms AS VARCHAR(20)) FROM grade_terms;

DROP TABLE grade_terms;
ALTER TABLE sheet DROP COLUMN clerk_limit;
ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN late_pct;
ALTER TABLE sheet DROP COLUMN due_cap;
== V36__claim_deferred.sql
-- An OPEN claim can be deferred to a date after the sheet's today: until the sheet's today reaches that date it counts
-- in no total, is not overdue, cannot be settled and is left unbound by a statement. Null: never deferred.
ALTER TABLE claim ADD COLUMN deferred_until DATE;
== V37__claim_proofs.sql
-- How many proofs a claim has: a claim whose due is above the sheet's proof threshold on its date cannot be settled or
-- approved while it has none.
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
== V38__sheet_permission.sql
-- The permission matrix: for an action (open, settle, void, reassign, close, reopen), the roles that may take it, as
-- a comma separated list (clerk, steward). Not dated. An action with no row keeps the standing rule: open, settle,
-- void and close by clerk and steward; reassign and reopen by steward.
CREATE TABLE sheet_permission (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    action   VARCHAR(20)  NOT NULL,
