== V40__sheet_grace_days.sql
-- The sheet's grace days: when its today moves past an open period's to-date by more than these, the period closes
-- itself. Not dated; null means off.
ALTER TABLE sheet ADD COLUMN grace_days INT;
== V41__claim_split_from.sql
-- The number of the claim a claim was split off; null unless it was split off another.
ALTER TABLE claim ADD COLUMN split_from VARCHAR(255);
== V42__person_watch.sql
-- The users watching a person, each at most once. A watcher is told (a NOTIFY record) whenever a claim of the person
-- is settled, approved or re-settled; watchers are told in the order they started watching.
